class Node{
                public:
                        pair<int,int>p;
                                Node* next;
                                        Node* prev;
                                                Node(pair<int,int>p) {
                                                            this->p = p;
                                                                        this->next = NULL;
                                                                                    this->prev = NULL;
                                                                                            }    
                                                                                            };
                                                                                            class LRUCache {
                                                                                                
                                                                                                    int capacity;
                                                                                                        int count = 0;
                                                                                                            Node* head;
                                                                                                                Node* tail;
                                                                                                                    unordered_map<int,Node*>m;
                                                                                                                        public:
                                                                                                                            
                                                                                                                                Node* removeNode(Node* temp) {
                                                                                                                                        temp->prev->next = temp->next;
                                                                                                                                                temp->next->prev = temp->prev;
                                                                                                                                                        return temp;
                                                                                                                                                            }
                                                                                                                                                                Node* addNode(Node* newNode) {
                                                                                                                                                                        // Node* newNode = new Node({temp->p.first,temp->p.second});
                                                                                                                                                                                newNode->prev = head;
                                                                                                                                                                                        newNode->next = head->next;
                                                                                                                                                                                                head->next->prev = newNode;
                                                                                                                                                                                                        head->next = newNode;
                                                                                                                                                                                                                return newNode;
                                                                                                                                                                                                                    }
                                                                                                                                                                                                                        LRUCache(int capacity) {
                                                                                                                                                                                                                                this->capacity = capacity;
                                                                                                                                                                                                                                        head = new Node({-1,-1});
                                                                                                                                                                                                                                                tail = new Node({-1,-1});

                                                                                                                                                                                                                                                        head->next = tail;
                                                                                                                                                                                                                                                                tail->prev = head;
                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                            int get(int key) {
                                                                                                                                                                                                                                                                                    if(m.find(key) != m.end()) {
                                                                                                                                                                                                                                                                                                Node* node = removeNode(m[key]);
                                                                                                                                                                                                                                                                                                            addNode(node);
                                                                                                                                                                                                                                                                                                                        return m[key]->p.second;
                                                                                                                                                                                                                                                                                                                                }else {
                                                                                                                                                                                                                                                                                                                                            return -1;
                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                void put(int key, int value) {
                                                                                                                                                                                                                                                                                                                                                                        if(m.find(key) != m.end()) {
                                                                                                                                                                                                                                                                                                                                                                                    Node* node = m[key];
                                                                                                                                                                                                                                                                                                                                                                                                node->p.second = value;
                                                                                                                                                                                                                                                                                                                                                                                                            removeNode(node);
                                                                                                                                                                                                                                                                                                                                                                                                                        addNode(node);
                                                                                                                                                                                                                                                                                                                                                                                                                                    // m[key] = node;
                                                                                                                                                                                                                                                                                                                                                                                                                                                // return value;
                                                                                                                                                                                                                                                                                                                                                                                                                                                        }else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if(count == capacity) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Node* node = tail->prev;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    removeNode(node);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    m.erase(node->p.first);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    delete node;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Node* newNode = new Node({key,value});
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    addNode(newNode);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    m[key] = newNode;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Node* newNode = new Node({key,value});
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                addNode(newNode);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                count++;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                m[key] = newNode;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        };
